// Проверка подписи RAHTIS на входящем отчёте о топливе.
//
// Платформа подписывает исходящий запрос тем же секретом, которым мы
// подписываем обратные: HMAC-SHA256 на AGENT_WEBHOOK_SECRET от строки
// `${timestamp}.${body}`, заголовок x-rahtis-signature вида sha256=<hex>.
//
// Без проверки вебхук открыт: кто узнал адрес, тот будет гонять
// OpenAI за наш счёт.

const crypto = require('crypto');

// Секрет для подписи.
//
// $env в узлах Code на n8n Cloud закрыт наглухо: с версии 2.0
// N8N_BLOCK_ENV_ACCESS_IN_NODE по умолчанию true, и на облаке этот
// переключатель недоступен. Поэтому секрет берётся из переменных n8n
// ($vars — планы Pro и Enterprise Cloud).
//
// Если у вас Starter, где переменных нет, впишите значение в SECRET
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.AGENT_WEBHOOK_SECRET) SECRET = $vars.AGENT_WEBHOOK_SECRET; } catch (e) {}
if (!SECRET) throw new Error('AGENT_WEBHOOK_SECRET не задан: создайте переменную в n8n или впишите значение в SECRET.');
const secret = SECRET;

// Сырое тело подписи. n8n отдаёт его по-разному: строкой, буфером,
// разобранным объектом, а при rawBody иногда двоичным вложением. Подпись
// считается от БАЙТОВ, которые прислала платформа, поэтому читаем все
// формы, а разбор JSON оставляем на потом.
function rawBody() {
  try {
    const bin = $input.item.binary;
    if (bin && bin.data && bin.data.data) return Buffer.from(bin.data.data, 'base64').toString('utf8');
  } catch (e) {}
  const b = $json.body;
  if (typeof b === 'string') return b;
  if (Buffer.isBuffer(b)) return b.toString('utf8');
  if (b && b.type === 'Buffer' && Array.isArray(b.data)) return Buffer.from(b.data).toString('utf8');
  return JSON.stringify(b || {});
}
const raw = rawBody();
const ts = $json.headers['x-rahtis-timestamp'] || '';
const given = $json.headers['x-rahtis-signature'] || '';

// Окно 300 секунд: перехваченный запрос нельзя повторить назавтра.
const age = Math.abs(Math.floor(Date.now() / 1000) - Number(ts));
const fresh = Number.isFinite(age) && age <= 300;

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(given);
const signed = a.length === b.length && crypto.timingSafeEqual(a, b);

let p = {};
try { p = JSON.parse(raw); } catch (e) { try { p = (typeof $json.body === 'object' && $json.body) || {}; } catch (e2) { p = {}; } }

const isPdf = p.mime === 'application/pdf';
const data = typeof p.data_base64 === 'string' ? p.data_base64 : '';
const text = typeof p.text === 'string' ? p.text.slice(0, 200000) : '';
return [{
  json: {
    ok: signed && fresh && (isPdf ? data.length > 0 : text.length > 0),
    why: signed ? (fresh ? null : 'stale') : 'signature',
    is_pdf: isPdf,
    data_base64: isPdf ? data : '',
    text: isPdf ? '' : text,
    file_name: typeof p.file_name === 'string' ? p.file_name.slice(0, 120) : 'report',
    plates: Array.isArray(p.plates) ? p.plates.filter((x) => typeof x === 'string').slice(0, 300) : [],
    country: typeof p.country === 'string' ? p.country.slice(0, 2) : 'FI',
  },
}];

// Запрос к OpenAI: строки заправок из месячного отчёта заправщика.
// PDF уходит файлом, CSV — текстом. Ответ — строго по схеме, чтобы сайт
// мог проверить каждое поле и показать строки перевозчику на проверку.
const PRODUCTS = ['DIESEL', 'HVO', 'ADBLUE', 'PETROL', 'LNG', 'LBG', 'CNG', 'CBG', 'OTHER'];
const system = [
  'You read monthly fuel card reports of a transport company (Neste, St1, Shell, Teboil, ABC, Circle K, DKV, UTA and others).',
  'Return every refuelling transaction as one row. Skip totals, subtotals, fees, shop items, car wash, oil and anything that is not fuel or AdBlue.',
  'date: YYYY-MM-DD. time: HH:MM in 24h, or null if the report has no time.',
  'plate: the vehicle registration as written in the report, or null. card: the fuel card number without spaces, or null.',
  'station: station name and town, short. odometer: the odometer / mileage entered at the pump in km, or null.',
  'product: DIESEL for diesel (also "DI", "Diesel", "Neste Pro Diesel", "V-Power Diesel"); HVO for renewable diesel (HVO100, "Neste MY Renewable Diesel", "uusiutuva diesel"); ADBLUE for AdBlue/DEF; PETROL for petrol (95E10, 98E5, bensiini); LNG, LBG (bio-LNG), CNG, CBG (bio-CNG, biokaasu) for gas; OTHER only for other fuels.',
  'quantity: litres, or kilograms for gas, as a number with a dot as the decimal separator.',
  'amount_gross: the amount paid INCLUDING VAT in euros. If the report shows only the amount without VAT, add the VAT shown in the report. If the currency is not EUR, use null.',
  'supplier: the fuel company that issued the report, or null.',
  'Known vehicle plates of this company: ' + ($json.plates.join(', ') || 'none') + '. Country: ' + $json.country + '.',
  'Never invent rows or values. If a value is not in the report, use null.',
].join(' ');

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['supplier', 'rows'],
  properties: {
    supplier: { type: ['string', 'null'] },
    rows: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['date', 'time', 'plate', 'card', 'station', 'product', 'quantity', 'amount_gross', 'odometer'],
        properties: {
          date: { type: 'string' },
          time: { type: ['string', 'null'] },
          plate: { type: ['string', 'null'] },
          card: { type: ['string', 'null'] },
          station: { type: ['string', 'null'] },
          product: { type: 'string', enum: PRODUCTS },
          quantity: { type: 'number' },
          amount_gross: { type: ['number', 'null'] },
          odometer: { type: ['number', 'null'] },
        },
      },
    },
  },
};

const user = $json.is_pdf
  ? [
      { type: 'file', file: { filename: $json.file_name.endsWith('.pdf') ? $json.file_name : $json.file_name + '.pdf', file_data: 'data:application/pdf;base64,' + $json.data_base64 } },
      { type: 'text', text: 'Extract the refuelling rows from this report.' },
    ]
  : 'Extract the refuelling rows from this CSV export:\n\n' + $json.text;

return [{ json: { payload: JSON.stringify({
  // gpt-4.1 и 4o отключают 14.01.2027; у gpt-6-luna нет temperature, усилие — low (отчёт длинный, таймаут 100 с).
  model: 'gpt-6-luna',
  reasoning_effort: 'low',
  response_format: { type: 'json_schema', json_schema: { name: 'fuel_report', strict: true, schema } },
  messages: [ { role: 'system', content: system }, { role: 'user', content: user } ],
}) } }];

// Ответ OpenAI → то, что ждёт сайт. Поля сайт проверит сам (src/lib/fuel/fuel.ts).
let out = { ok: false, supplier: null, rows: [] };
try {
  const data = JSON.parse($json.choices[0].message.content);
  out = { ok: Array.isArray(data.rows), supplier: typeof data.supplier === 'string' ? data.supplier.slice(0, 60) : null, rows: Array.isArray(data.rows) ? data.rows.slice(0, 1000) : [] };
} catch (e) {
  out = { ok: false, supplier: null, rows: [], detail: ($json.error && $json.error.message) || 'parse' };
}
return [{ json: out }];
